=====record.h 1-80=====
/* On-disk record format — mechanism D (D-034, with D-037 and D-040; extends 🔒 C.1, C.2).
 *
 * The constraint: power can disappear at any instant. The box shuts down cleanly when
 * its supercapacitor allows (D-024), but a cold-start crank, a pulled cable or an empty
 * bank can still cut a write, so recovery must find the torn tail and truncate it
 * without losing anything before it.
 *
 * Therefore every record is (a) self-framing: a magic number to resynchronize on and a
 * length; and (b) CRC'd over everything before the CRC, so a partly written record is
 * detectable rather than merely wrong. Records are written in committed batches (D-025):
 * a batch with no COMMIT on disk is discarded at recovery.
 *
 * Layout (little-endian, the Pi's order): a 40-byte header, a body whose size depends
 * on its kind, then a CRC32 of header and body.
 */
#ifndef CARWATCH_RECORD_H
#define CARWATCH_RECORD_H

#include <float.h>
#include <stddef.h>
#include <stdint.h>

#define REC_MAGIC          0x31525743u   /* the bytes "CWR1" */
#define REC_HDR_SIZE       40u
#define REC_CRC_SIZE       4u
#define REC_EVENT_TEXT_MAX 200u
#define REC_MAX_BODY       (4u + REC_EVENT_TEXT_MAX)
#define REC_MAX_SIZE       (REC_HDR_SIZE + REC_MAX_BODY + REC_CRC_SIZE)

typedef enum {
    REC_SAMPLE   = 1,
    REC_BEGIN    = 2,
    REC_COMMIT   = 3,
    REC_BOOT     = 4,
    REC_SHUTDOWN = 5,
    REC_EVENT    = 6
} rec_kind_t;

#define REC_FLAG_WALL_UNTRUSTED 0x01u   /* the clock lost its backup this boot (D-030) */

typedef struct {
    uint32_t magic;      /* REC_MAGIC — resync anchor for the recovery scan */
    uint16_t kind;       /* rec_kind_t */
    uint16_t body_len;   /* bytes of body; each kind allows only its own size */
    uint64_t seq;        /* per log, never reused; a gap is a detected loss, not a hidden one */
    uint64_t mono_ns;    /* CLOCK_MONOTONIC: at capture for samples, at write otherwise */
    uint64_t wall_ns;    /* Unix time from the real-time clock (D-030) */
    uint8_t  src;        /* data_src_t: 1 live, 2 replay, 3 synth; 0 is invalid (D-040) */
    uint8_t  flags;      /* REC_FLAG_* */
    uint16_t reserved;   /* zero */
    uint32_t boot_id;    /* increments every boot; mono_ns compares only within one */
} rec_hdr_t;

/* Mode 0x00 is never sent to a car, so it names the box's own sensors (D-037). */
#define REC_MODE_BOX  0x00u
#define REC_PID_PROBE 0x01u   /* the DS18B20, value in °C */
#define REC_RAW_MAX   5u      /* the most data bytes a single-frame Mode 01 reply carries */

typedef struct {
    uint8_t mode;
    uint8_t pid;
    uint8_t raw_len;           /* 0 to REC_RAW_MAX */
    uint8_t raw[REC_RAW_MAX];  /* the reply's data bytes, kept beside the decoded value */
    float   value;
} rec_sample_t;

typedef struct { uint64_t txn_id; } rec_begin_t;

typedef struct {
    uint64_t txn_id;
    uint32_t records;    /* samples in the batch */
    uint32_t reserved;
} rec_commit_t;

typedef enum { REC_PREV_CLEAN = 0, REC_PREV_RECOVERED = 1, REC_PREV_FIRST = 2 } rec_prev_end_t;

typedef struct {
    uint8_t  prev_end;   /* rec_prev_end_t */
    uint8_t  reserved[3];
    uint32_t bytes_truncated;
=====wal.h 1-45=====
/* storaged's write-ahead log: mechanism D (D-025, D-034, D-035, D-041).
 *
 * Records go to the newest segment file, log-<first seq>.cwr, in batches: BEGIN, the
 * records, COMMIT, then one fsync. A batch counts only once its COMMIT is on disk. At
 * open, recovery scans the newest segment, keeps everything up to the last COMMIT and
 * truncates the rest (undo is truncation: nothing is ever overwritten, C.1), then writes
 * a boot batch saying whether the last session ended cleanly.
 */
#ifndef CARWATCH_WAL_H
#define CARWATCH_WAL_H

#include "store/record.h"

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define WAL_SEGMENT_BYTES   (16u * 1024u * 1024u)   /* D-034 */
#define WAL_BATCH_SAMPLES   64u                     /* D-035 */
#define WAL_BATCH_NS        1000000000ull           /* D-035: one second */
#define WAL_BUF_BYTES       (WAL_BATCH_SAMPLES * 56u + 32u * REC_MAX_SIZE)
#define WAL_NAMESPACES      2u    /* sample namespaces: 0 the car (Mode 01), 1 the box (D-037) */

/* Event codes storaged writes itself (D-042: sender byte 0x05). */
#define WAL_EV_RING_GEN     0x0501u   /* "ns=<0|1> gen=<hex>": which ring instance fed us */
#define WAL_EV_RING_SEQ     0x0502u   /* "ns=<0|1> seq=<hex>": last ring slot in this batch */

/* What a scan of one segment found. */
typedef struct {
    size_t   committed_len;       /* bytes up to and including the last COMMIT */
    bool     any_committed;
    bool     ended_clean;         /* the last committed batch ended with a SHUTDOWN */
    uint64_t last_seq, last_txn;
    uint32_t last_boot_id;
    uint32_t samples_committed;   /* in the whole segment */
    uint32_t records_lost;        /* decodable samples after the last COMMIT */
    uint64_t last_mono[WAL_NAMESPACES];   /* last committed sample's mono_ns, per namespace */
    uint64_t ring_gen[WAL_NAMESPACES];    /* last WAL_EV_RING_GEN, per namespace (0: none) */
    bool     has_ring_seq[WAL_NAMESPACES];
    uint64_t ring_seq[WAL_NAMESPACES];    /* last committed WAL_EV_RING_SEQ, per namespace */
} wal_scan_t;

typedef struct {
    char       dir[200];
    int        fd;
=====source.h=====
/* Where statusd gets its data (D-043, D-045): one function, one request line in, one reply
 * out. A source answers in the control socket's reply format (kv.h), so statusd cannot tell
 * the synthetic source from the real one, a client of /run/carwatch/ctl.sock. Replacing it
 * is the one line in statusd that builds the source_t.
 */
#ifndef CARWATCH_SOURCE_H
#define CARWATCH_SOURCE_H

#include <stddef.h>
#include <sys/types.h>

typedef struct {
    /* request is one D-043 request line without its newline, in the typed grammar of kv.h:
     * series pid="0C" from="-5m" to="now". Writes a whole reply to out[cap], NUL-terminated
     * and ending in "ok" or "err <code> <reason>", and returns its length. A refused request
     * is still a reply. Returns -1, never half a reply, only if the reply does not fit. */
    ssize_t (*query)(void *ctx, const char *request, char *out, size_t cap);
    void     *ctx;
} source_t;

static inline ssize_t source_query(const source_t *s, const char *request, char *out,
                                   size_t cap)
{
    return s->query(s->ctx, request, out, cap);
}

#endif
