/* Every descriptor the server makes is non-blocking and close-on-exec, so a poll loop
 * never stalls on one connection and no child inherits a socket. Linux sets both in the
 * call itself (accept4, SOCK_NONBLOCK | SOCK_CLOEXEC); macOS, where the tests also run,
 * has neither, so the flags are set with fcntl right after the call. */
static int nonblock_cloexec(int fd)
{
    int fl = fcntl(fd, F_GETFL);
    if (fl < 0 || fcntl(fd, F_SETFL, fl | O_NONBLOCK) < 0) return -1;
    int fdfl = fcntl(fd, F_GETFD);
    if (fdfl < 0 || fcntl(fd, F_SETFD, fdfl | FD_CLOEXEC) < 0) return -1;
    return 0;
}

static int accept_nonblock_cloexec(int listen_fd)
{
#if defined(SOCK_NONBLOCK) && defined(SOCK_CLOEXEC)
    return accept4(listen_fd, NULL, NULL, SOCK_NONBLOCK | SOCK_CLOEXEC);
#else
    int fd = accept(listen_fd, NULL, NULL);
    if (fd >= 0 && nonblock_cloexec(fd) < 0) {
        int saved = errno;
        close(fd);
        errno = saved;
        return -1;
    }
    return fd;
#endif
}

